WITH session_totals AS (SELECT session_id, SUM(CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END) AS add_to_cart_count, MAX(duration_sec) AS max_duration_sec FROM web_events WHERE page NOT IN ('/product', '/checkout', '/cart') GROUP BY session_id) SELECT s.customer_id, s.browser, st.add_to_cart_count, st.max_duration_sec FROM sessions s INNER JOIN session_totals st ON s.id = st.session_id WHERE st.add_to_cart_count > 20
